ABSTRACT_CN = (
    "\u9488\u5bf9\u7164\u77ff\u4f5c\u4e1a\u89c4\u7a0b\u7bc7\u5e45\u957f\u3001\u6761\u6b3e\u5173\u8054\u590d\u6742\u3001\u4eba\u5de5\u5ba1\u67e5\u6548\u7387\u4f4e\u4e14\u73b0\u573a\u98ce\u9669\u4fe1\u606f\u591a\u6e90\u96be\u878d\u5408\u7b49\u95ee\u9898\uff0c\u672c\u4f5c\u54c1\u8bbe\u8ba1\u4e86\u4e00\u5957\u9762\u5411\u89c4\u7a0b\u5ba1\u67e5\u4e0e\u73b0\u573a\u7814\u5224\u7684\u79fb\u52a8\u7aef\u534f\u540c\u591a\u667a\u80fd\u4f53\u7cfb\u7edf\u3002\u7cfb\u7edf\u91c7\u7528 MinerU \u8fdb\u884c OCR \u4e0e\u7248\u9762\u89e3\u6790\uff0c\u4ee5 BGE-M3 \u6784\u5efa\u7a20\u5bc6\u4e0e\u7a00\u758f\u878d\u5408\u7684\u77e5\u8bc6\u8868\u793a\uff0c\u5e76\u901a\u8fc7 Milvus \u548c MongoDB \u5b8c\u6210\u5411\u91cf\u68c0\u7d22\u4e0e\u4e1a\u52a1\u6570\u636e\u7ba1\u7406\u3002\u5728\u5ba1\u67e5\u8fc7\u7a0b\u4e2d\uff0c\u4e3b\u667a\u80fd\u4f53\u57fa\u4e8e LangChain/LangGraph \u8fdb\u884c\u4efb\u52a1\u7406\u89e3\u3001\u5de5\u5177\u8c03\u7528\u548c\u591a\u667a\u80fd\u4f53\u5e76\u884c\u8c03\u5ea6\uff0c\u5c06 Qwen \u5927\u6a21\u578b\u7684\u8bed\u4e49\u7406\u89e3\u80fd\u529b\u4e0e\u786e\u5b9a\u6027\u4ee3\u7801\u6838\u9a8c\u7ed3\u5408\uff0c\u63d0\u9ad8\u6570\u503c\u9608\u503c\u548c\u5408\u89c4\u5224\u65ad\u7684\u53ef\u4fe1\u5ea6\u3002\u7cfb\u7edf\u540c\u65f6\u8bbe\u8ba1 Web \u7aef\u4e0e\u5fae\u4fe1\u5c0f\u7a0b\u5e8f\u7aef\uff0c\u5c0f\u7a0b\u5e8f\u590d\u7528\u624b\u673a\u6444\u50cf\u5934\u3001\u9ea6\u514b\u98ce\u548c\u7f51\u7edc\u80fd\u529b\u5b9e\u73b0\u6587\u5b57\u3001\u8bed\u97f3\u4e0e\u56fe\u7247\u4e0a\u62a5\uff0c\u652f\u6301\u73b0\u573a\u8ffd\u95ee\u3001\u98ce\u9669\u7b49\u7ea7\u5c55\u793a\u548c\u7ecf\u9a8c\u56de\u6d41\u3002\u672c\u65b9\u6848\u53ef\u4e3a\u7164\u77ff\u5b89\u5168\u5ba1\u67e5\u3001\u73b0\u573a\u98ce\u9669\u7814\u5224\u548c\u884c\u4e1a\u77e5\u8bc6\u6c89\u6dc0\u63d0\u4f9b\u5de5\u7a0b\u5316\u652f\u6491\u3002"
)
ABSTRACT_EN = (
    "This work presents a mobile collaborative multi-agent system for coal mine safety document review and on-site risk assessment. The system combines OCR and layout parsing, hybrid retrieval, vector search, task-oriented agents and deterministic tool verification. MinerU is used for document parsing, BGE-M3 for embedding and reranking, Milvus for vector indexes, MongoDB for business data, and Redis for cache and asynchronous task buffering. A master agent built with LangChain and LangGraph plans the review workflow, dispatches professional agents, invokes Qwen-based reasoning and calls code tools for numerical checks. The Web client supports document review and human feedback, while the WeChat mini program uses the phone camera, microphone and network capability to submit text, voice and images from field scenarios. The proposed system provides a traceable engineering framework for regulation review, field questioning, risk judgment and experience reuse."
)


def is_heading(p) -> bool:
    t = p.text.strip()
    return p.style.name.startswith("Heading") or t.startswith(("\u7b2c\u4e00\u7ae0", "\u7b2c\u4e8c\u7ae0", "\u7b2c\u4e09\u7ae0", "\u7b2c\u56db\u7ae0", "\u7b2c\u4e94\u7ae0", "\u7b2c\u516d\u7ae0", "\u7b2c\u4e03\u7ae0", "\u7814\u7a76\u6210\u679c", "\u53c2\u8003\u6587\u732e")) or re.match(r"^[1-7]\.\d+", t)


def clean_heading_text(text: str) -> str:
    text = text.strip()
    text = re.sub(r"\uff08\u6210\u5458[^）]*\uff09", "", text)
    text = re.sub(r"\uff08[^）]*\u4e3b\u7b14[^）]*\uff09", "", text)
    text = re.sub(r"\uff08[^）]*\u534f\u540c\u5b8c\u5584[^）]*\uff09", "", text)
    text = text.replace("\u7b2c\u5341\u4e5d\u5c4a", "\u7b2c\u4e8c\u5341\u4e00\u5c4a")
    return text.strip()


def key_for_heading(text: str) -> str:
    text = clean_heading_text(text)
    if text.startswith("3.3 "):
        return "3.3 \u4e3b\u667a\u80fd\u4f53\u81ea\u4e3b\u51b3\u7b56\u3001\u5de5\u5177\u6838\u9a8c\u4e0e\u591a\u667a\u80fd\u4f53\u5f02\u6b65\u5e76\u884c\u5ba1"
    return text


def paragraph_has_drawing(p) -> bool:
    return bool(p._p.xpath(".//w:drawing"))


def is_caption_text(text: str) -> bool:
    text = text.strip()
    return text.startswith(("\u56fe", "\u8868"))


def remove_element(el) -> None:
    parent = el.getparent()
    if parent is not None:
        parent.remove(el)


def add_page_field(paragraph):
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = paragraph.add_run()
    fld_char1 = OxmlElement("w:fldChar")
    fld_char1.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = "PAGE"
    fld_char2 = OxmlElement("w:fldChar")
    fld_char2.set(qn("w:fldCharType"), "end")
    run._r.append(fld_char1)
    run._r.append(instr)
    run._r.append(fld_char2)


def set_run_font(run, size=10.5, bold=False, east_asia="\u5b8b\u4f53", ascii_font="Times New Roman"):
    run.font.size = Pt(size)
    run.font.bold = bold
    run.font.name = ascii_font
    run._element.rPr.rFonts.set(qn("w:eastAsia"), east_asia)


def format_paragraph(p, role="body"):
    fmt = p.paragraph_format
    fmt.line_spacing = Pt(20)
    fmt.space_before = Pt(0)
    fmt.space_after = Pt(0)
    if role == "body":
        fmt.first_line_indent = Pt(21)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        for r in p.runs:
            set_run_font(r, 10.5, False, "\u5b8b\u4f53")
    elif role == "caption":
        fmt.first_line_indent = None
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        for r in p.runs:
            set_run_font(r, 10.5, False, "\u5b8b\u4f53")
    elif role == "h1":
        fmt.first_line_indent = None
        fmt.space_before = Pt(12)
        fmt.space_after = Pt(6)
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        for r in p.runs:
            set_run_font(r, 18, True, "\u9ed1\u4f53")
    elif role == "h2":
        fmt.first_line_indent = None
        fmt.space_before = Pt(6)
        fmt.space_after = Pt(3)
        p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        for r in p.runs:
            set_run_font(r, 12, True, "\u9ed1\u4f53")
    elif role == "front":
        fmt.first_line_indent = None
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        for r in p.runs:
            set_run_font(r, 12, True, "\u9ed1\u4f53")


def insert_paragraph_after(paragraph, text: str, style=None):
    new_p = OxmlElement("w:p")
    paragraph._p.addnext(new_p)
    new_para = paragraph._parent.add_paragraph()
    new_para._p = new_p
    if style is not None:
        new_para.style = style
    new_para.add_run(text)
    return new_para


def insert_many_after(paragraph, texts: list[str], style_name: str = "Normal") -> list:
    inserted = []
    anchor = paragraph
    for text in texts:
        p = insert_paragraph_after(anchor, text, style_name)
        inserted.append(p)
        anchor = p
    return inserted


def body_elements(doc):
    return list(doc.element.body)


def heading_paragraphs(doc):
    return [p for p in doc.paragraphs if is_heading(p)]


def compress_sections(doc: Document) -> None:
    heads = heading_paragraphs(doc)
    body = doc.element.body
    for idx in range(len(heads) - 1, -1, -1):
        h = heads[idx]
        heading_text = clean_heading_text(h.text)
        key = key_for_heading(heading_text)
        if "\u53c2\u8003\u6587\u732e" in heading_text:
            h.text = "\u53c2\u8003\u6587\u732e"
            continue
        h.text = heading_text
        start = body.index(h._p)
        end = body.index(heads[idx + 1]._p) if idx + 1 < len(heads) else len(body) - 1
        for el in list(body)[start + 1 : end]:
            if el.tag == qn("w:p"):
                p_obj = None
                for p in doc.paragraphs:
                    if p._p is el:
                        p_obj = p
                        break
                if p_obj is None:
                    continue
                text = p_obj.text.strip()
                if paragraph_has_drawing(p_obj) or is_caption_text(text):
                    continue
                remove_element(el)
        insert_texts = CONTENTS.get(key, [])
        for p in reversed(insert_texts):
            insert_paragraph_after(h, p, "Normal")


def rebuild_front_matter(doc: Document) -> None:
    for p in doc.paragraphs:
        text = p.text.strip()
        if "\u7b2c\u5341\u4e5d\u5c4a\u4e2d\u56fd\u7814\u7a76\u751f\u7535\u5b50\u8bbe\u8ba1\u7ade\u8d5b" in text:
            p.text = "\u7b2c\u4e8c\u5341\u4e00\u5c4a\u4e2d\u56fd\u7814\u7a76\u751f\u7535\u5b50\u8bbe\u8ba1\u7ade\u8d5b\u6280\u672f\u8bba\u6587"
        elif "\u79fb\u52a8\u7aef\u534f\u540c\u591a\u667a\u80fd\u4f53\u7cfb\u7edf" in text:
            p.text = TITLE

    abstract = next(p for p in doc.paragraphs if p.text.strip().startswith("\u6458"))
    first_h1 = next(p for p in doc.paragraphs if clean_heading_text(p.text).startswith("\u7b2c\u4e00\u7ae0"))
    body = doc.element.body
    start = body.index(abstract._p)
    end = body.index(first_h1._p)
    for el in list(body)[start + 1 : end]:
        remove_element(el)
    abstract.text = "\u6458  \u8981"
    front = [
        ABSTRACT_CN,
        "\u5173\u952e\u8bcd\uff1a\u7164\u77ff\u5b89\u5168\uff1b\u591a\u667a\u80fd\u4f53\uff1b\u68c0\u7d22\u589e\u5f3a\u751f\u6210\uff1b\u5fae\u4fe1\u5c0f\u7a0b\u5e8f\uff1b\u6570\u636e\u98de\u8f6e",
        "Abstract",
        ABSTRACT_EN,
        "Keywords: coal mine safety; multi-agent system; retrieval-augmented generation; WeChat mini program; data flywheel",
        "\u76ee  \u5f55",
        "\u7b2c\u4e00\u7ae0 \u7814\u7a76\u80cc\u666f\u548c\u610f\u4e49",
        "\u7b2c\u4e8c\u7ae0 \u4f5c\u54c1\u96be\u70b9\u4e0e\u521b\u65b0",
        "2.1 \u5f02\u6784\u89c4\u5219\u6587\u6863\u7684\u7ed3\u6784\u7edf\u4e00\u4e0e\u77e5\u8bc6\u7ec4\u7ec7\u96be\u9898",
        "2.2 \u957f\u7bc7\u5f85\u5ba1\u6587\u6863\u7684\u8bed\u4e49\u4fdd\u6301\u4e0e\u7cbe\u51c6\u8bc1\u636e\u68c0\u7d22\u96be\u9898",
        "2.3 \u590d\u6742\u5ba1\u67e5\u4efb\u52a1\u7684\u81ea\u4e3b\u51b3\u7b56\u4e0e\u5e76\u884c\u534f\u540c\u96be\u9898",
        "2.4 \u591a\u6765\u6e90\u5ba1\u67e5\u7ecf\u9a8c\u7684\u5206\u5c42\u6c89\u6dc0\u4e0e\u590d\u7528\u96be\u9898",
        "\u7b2c\u4e09\u7ae0 \u65b9\u6848\u8bba\u8bc1\u4e0e\u8bbe\u8ba1",
        "\u7b2c\u56db\u7ae0 \u539f\u7406\u5206\u6790\u53ca\u786c\u4ef6\u7535\u8def\u56fe",
        "\u7b2c\u4e94\u7ae0 \u8f6f\u4ef6\u8bbe\u8ba1\u4e0e\u6d41\u7a0b",
        "\u7b2c\u516d\u7ae0 \u7cfb\u7edf\u6d4b\u8bd5\u4e0e\u5206\u6790",
        "\u7b2c\u4e03\u7ae0 \u603b\u7ed3",
    ]
    inserted = insert_many_after(abstract, front)
    inserted[-1].add_run().add_break(WD_BREAK.PAGE)


def apply_styles(doc: Document) -> None:
    section = doc.sections[0]
    section.page_height = Cm(29.7)
    section.page_width = Cm(21)
    section.top_margin = Cm(2.5)
    section.bottom_margin = Cm(2.5)
    section.left_margin = Cm(2.5)
    section.right_margin = Cm(2.5)
    header = section.header
    header.paragraphs[0].text = "\u7b2c\u4e8c\u5341\u4e00\u5c4a\u4e2d\u56fd\u7814\u7a76\u751f\u7535\u5b50\u8bbe\u8ba1\u7ade\u8d5b"
    header.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
    hp = header.add_paragraph(TITLE)
    hp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    for p in header.paragraphs:
        for r in p.runs:
            set_run_font(r, 9, False, "\u5b8b\u4f53")
    footer = section.footer
    footer.paragraphs[0].clear()
    add_page_field(footer.paragraphs[0])

    for p in doc.paragraphs:
        text = p.text.strip()
        if not text:
            continue
        if is_caption_text(text):
            format_paragraph(p, "caption")
        elif p.style.name.startswith("Heading 1") or text.startswith(("\u7b2c\u4e00\u7ae0", "\u7b2c\u4e8c\u7ae0", "\u7b2c\u4e09\u7ae0", "\u7b2c\u56db\u7ae0", "\u7b2c\u4e94\u7ae0", "\u7b2c\u516d\u7ae0", "\u7b2c\u4e03\u7ae0", "\u7814\u7a76\u6210\u679c", "\u53c2\u8003\u6587\u732e")):
            p.style = doc.styles["Heading 1"]
            format_paragraph(p, "h1")
        elif p.style.name.startswith("Heading 2") or re.match(r"^[1-7]\.\d+", text):
            p.style = doc.styles["Heading 2"]
            format_paragraph(p, "h2")
        elif text in {"\u6458  \u8981", "Abstract", "\u76ee  \u5f55"}:
            format_paragraph(p, "front")
        else:
            format_paragraph(p, "body")

    for table in doc.tables:
        table.autofit = True
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    p.paragraph_format.line_spacing = Pt(20)
                    p.paragraph_format.space_before = Pt(0)
                    p.paragraph_format.space_after = Pt(0)
                    for r in p.runs:
                        set_run_font(r, 9, False, "\u5b8b\u4f53")


def count_chars(doc: Document) -> tuple[int, int]:
    parts = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                parts.append(cell.text)
    text = "\n".join(parts)
    return len(re.findall(r"[\u4e00-\u9fff]", text)), len(re.sub(r"\s+", "", text))


def main() -> None:
    doc = Document(str(SRC))
    compress_sections(doc)
    rebuild_front_matter(doc)
    apply_styles(doc)
    doc.save(str(OUT))
    cn, nonspace = count_chars(doc)
    print(f"output={OUT}")
    print(f"cn_chars={cn}")
    print(f"nonspace_chars={nonspace}")
    print(f"paragraphs={len(doc.paragraphs)} tables={len(doc.tables)} shapes={len(doc.inline_shapes)}")


if __name__ == "__main__":
    main()
